tools.example:
pd = makedist('Weibull', 'a', 3, 'b', 1.5);
x = 0:0.05:8;
plot(x, pdf(pd, x))
fprintf('Mean = %.3f, Var = %.3f\n', mean(pd), var(pd));
pdt = truncate(pd, 1, 5);

load hospital
x = hospital.Weight;
pd = fitdist(x, 'Normal');
fprintf('mu = %.2f, sigma = %.2f\n', pd.mu, pd.sigma);
ci = paramci(pd, 'Alpha', 0.05);
histfit(x, 12, 'normal')

x = linspace(-5, 15, 400);
y1 = pdf('Normal', x, 5, 2);
pd = makedist('Gamma', 'a', 2, 'b', 2);
y2 = pdf(pd, x);
plot(x, y1, x, y2); legend('N(5,2)','Gamma(2,2)')

pd = makedist('Normal', 'mu', 100, 'sigma', 15);
p = cdf(pd, 130)              % P(X <= 130)
tail = cdf(pd, 130, 'upper')  % P(X > 130)
fprintf('%.4f above 130\n', tail);

pd = makedist('Normal', 'mu', 0, 'sigma', 1);
crit = icdf(pd, [0.025 0.975])   % -1.96, 1.96
q = icdf('Chisquare', 0.95, 3);

rng(42)
pd = makedist('Weibull', 'a', 2, 'b', 1.5);
x = random(pd, 1000, 1);
y = random('Poisson', 4, 1000, 1);
histogram(x, 30)

rng(0)
x = normrnd(10, 2, 1000, 1);
fprintf('sample mean %.3f, std %.3f\n', mean(x), std(x));
heteroskedastic = normrnd(0, linspace(1, 5, 100));

rng(1)
mu = [2 3];
Sigma = [1 0.8; 0.8 2];
X = mvnrnd(mu, Sigma, 500);
scatter(X(:,1), X(:,2), 10, 'filled')
disp(cov(X))

z = 2.5;
pTwoSided = 2 * normcdf(-abs(z))
pUpper = normcdf(z, 0, 1, 'upper')

rng(3)
y = exprnd(5, 200, 1);
cens = rand(200,1) < 0.2;
[f, x, lo, up] = ecdf(y, 'Censoring', cens, 'Function', 'survivor');
stairs(x, f); hold on; stairs(x, [lo up], ':')

rng(5)
x = [normrnd(2,0.5,300,1); normrnd(6,1,200,1)];
[f, xi] = ksdensity(x, 'Bandwidth', 0.3);
histogram(x, 40, 'Normalization', 'pdf'); hold on
plot(xi, f, 'LineWidth', 2)

load carsmall
mdl = fitlm(Weight, MPG);
r = mdl.Residuals.Raw;
qqplot(r)
title('Normal Q-Q plot of residuals')

rng(1)
x = lognrnd(0, 1, 1000, 1);
q = prctile(x, [5 25 50 75 95])
iqr_range = prctile(x, 75) - prctile(x, 25);

rng(1)
X = randn(1000, 3);
q = quantile(X, [0.025 0.5 0.975])
deciles = quantile(X(:,1), 9);

load fisheriris
[Z, mu, sigma] = zscore(meas);
newObs = [5.1 3.5 1.4 0.2];
newZ = (newObs - mu) ./ sigma;
[coeff, score] = pca(Z);

load fisheriris
[Xn, C, S] = normalize(meas, 'range', [0 1]);
Xtest = normalize([5.0 3.4 1.5 0.2], 'center', C, 'scale', S);
robustZ = normalize(meas, 'zscore', 'robust');

before = [72 68 75 80 71 69 77 74];
after  = [70 65 72 76 70 66 74 71];
[h, p, ci, stats] = ttest(before, after, 'Alpha', 0.05);
fprintf('h=%d p=%.4f t=%.3f df=%d\n', h, p, stats.tstat, stats.df);

load carsmall
mpgUSA = MPG(strcmp(cellstr(Origin), 'USA'));
mpgJPN = MPG(strcmp(cellstr(Origin), 'Japan'));
[h, p, ci, stats] = ttest2(mpgUSA, mpgJPN, 'Vartype', 'unequal');
fprintf('p = %.4g, CI = [%.2f %.2f]\n', p, ci);

rng(0)
x = normrnd(0, 1, 50, 1);
y = normrnd(0, 2, 50, 1);
[h, p, ci, stats] = vartest2(x, y);
fprintf('F = %.3f, p = %.4g\n', stats.fstat, p);

load carsmall
[p, tbl, stats] = anova1(MPG, Origin, 'off');
fprintf('p = %.4g\n', p);
figure, c = multcompare(stats);

load carbig
[p, tbl, stats] = anovan(MPG, {org, when}, ...
    'model', 'interaction', 'varnames', {'Origin','Year'});
figure, multcompare(stats, 'Dimension', [1 2]);

load carsmall
[~, ~, stats] = anova1(MPG, Origin, 'off');
[c, m, h, gnames] = multcompare(stats, 'CType', 'bonferroni', 'Display', 'off');
tbl = array2table(c, 'VariableNames', ...
    {'G1','G2','LowerCI','Diff','UpperCI','pValue'});

load carsmall
[p, tbl, stats] = kruskalwallis(MPG, Origin, 'off');
fprintf('Kruskal-Wallis p = %.4g\n', p);
c = multcompare(stats, 'Display', 'off');

rng(0)
x = exprnd(2, 30, 1);
y = exprnd(3, 35, 1);
[p, h, stats] = ranksum(x, y);
fprintf('p = %.4g, ranksum = %g\n', p, stats.ranksum);

before = [12 15 11 18 14 13 16];
after  = [10 14 11 15 12 12 14];
[p, h, stats] = signrank(before, after, 'Tail', 'right');
fprintf('p = %.4f\n', p);

rng(4)
x = normrnd(5, 2, 200, 1);
pd = makedist('Normal', 'mu', 5, 'sigma', 2);
[h, p, ksstat] = kstest(x, 'CDF', pd);
fprintf('h=%d p=%.4f D=%.4f\n', h, p, ksstat);

rng(6)
x1 = normrnd(0, 1, 100, 1);
x2 = normrnd(0.5, 1.5, 120, 1);
[h, p, d] = kstest2(x1, x2);
fprintf('h=%d p=%.4g D=%.3f\n', h, p, d);

load carsmall
[h, p] = lillietest(MPG(~isnan(MPG)));
fprintf('Normality rejected: %d (p = %.4f)\n', h, p);

rng(8)
x = trnd(4, 300, 1);       % heavy tails
[h, p, jbstat] = jbtest(x, 0.05, 1e-3);
fprintf('h=%d p=%.4f JB=%.2f\n', h, p, jbstat);

rng(9)
x = gamrnd(2, 3, 250, 1);
[hNorm, pNorm] = adtest(x);
pd = fitdist(x, 'Gamma');
[hGam, pGam] = adtest(x, 'Distribution', pd, 'MCTol', 1e-2);
fprintf('normal p=%.4f, gamma p=%.4f\n', pNorm, pGam);

rng(10)
x = poissrnd(4, 500, 1);
pd = fitdist(x, 'Poisson');
[h, p, st] = chi2gof(x, 'CDF', pd, 'NParams', 1);
fprintf('chi2 = %.2f, df = %d, p = %.4f\n', st.chi2stat, st.df, p);

load fisheriris
[rho, p] = corr(meas, 'type', 'Spearman');
heatmap(rho)
significant = p < 0.05;

load carbig
X = [Acceleration Displacement Horsepower];
Z = Weight;
keep = ~any(isnan([X Z]), 2);
[rho, p] = partialcorr(X(keep,:), Z(keep), 'type', 'Pearson');
disp(rho)
